select is((select vat_satang from public.invoices where id='bd000000-0000-4000-8000-000000000030'),7000::bigint,'exclusive VAT is seven percent');
select is((select total_satang from public.invoices where id='bd000000-0000-4000-8000-000000000030'),107000::bigint,'gross total includes VAT');
select is((select wht_satang from public.invoices where id='bd000000-0000-4000-8000-000000000030'),3000::bigint,'WHT uses pre-VAT base');
select is((select amount_satang from public.invoices where id='bd000000-0000-4000-8000-000000000030'),104000::bigint,'payment readers collect amount due after WHT');
select throws_ok($$update public.invoices set wht_rate_bps=400 where id='bd000000-0000-4000-8000-000000000030'$$,'P0001','Invalid tax inputs','unsupported WHT rejected');
select lives_ok($$select public.issue_invoice('bd000000-0000-4000-8000-000000000010','bd000000-0000-4000-8000-000000000030',(select version from public.invoices where id='bd000000-0000-4000-8000-000000000030'),'bd000000-0000-4000-8000-000000000040')$$,'VAT invoice issues atomically');
select is((select snapshot->'document'->>'vatSatang' from public.invoice_snapshots where invoice_id='bd000000-0000-4000-8000-000000000030'),'7000','snapshot freezes VAT');
