select is((select snapshot->'document'->>'amountDueSatang' from public.invoice_snapshots where invoice_id='bd000000-0000-4000-8000-000000000030'),'104000','snapshot freezes amount due');
select is((select snapshot->'lines'->0->>'taxRateBps' from public.invoice_snapshots where invoice_id='bd000000-0000-4000-8000-000000000030'),'700','snapshot freezes rate per line');
