select is((select snapshot->'buyer'->>'branchLabel' from public.invoice_snapshots where invoice_id='bd000000-0000-4000-8000-000000000030'),'Branch 001','buyer branch frozen');
select throws_ok($$update public.invoices set wht_rate_bps=100 where id='bd000000-0000-4000-8000-000000000030'$$,'P0001','Issued tax content is frozen','issued WHT immutable');
select throws_ok($$update public.invoices set total_satang=1 where id='bd000000-0000-4000-8000-000000000030'$$,'P0001','Issued tax content is frozen','issued gross header immutable');
select throws_ok($$update public.invoice_items set tax_rate_bps=0 where invoice_id='bd000000-0000-4000-8000-000000000030'$$,'P0001','Issued or payment evidence locks invoice lines','issued tax rates immutable');
