insert into public.invoices(id,org_id,client_id,number) values ('bd000000-0000-4000-8000-000000000031','bd000000-0000-4000-8000-000000000010','bd000000-0000-4000-8000-000000000020','VAT-INCLUSIVE');
insert into public.invoice_items(org_id,invoice_id,description,unit_price_satang,tax_rate_bps) values ('bd000000-0000-4000-8000-000000000010','bd000000-0000-4000-8000-000000000031','Inclusive service',107000,700);
