select is((select wht_satang from public.invoices where id='bd000000-0000-4000-8000-000000000031'),2700::bigint,'discount before WHT');
select is((select amount_satang from public.invoices where id='bd000000-0000-4000-8000-000000000031'),93600::bigint,'discounted inclusive amount due');
select lives_ok($$select public.issue_invoice('bd000000-0000-4000-8000-000000000010','bd000000-0000-4000-8000-000000000031',(select version from public.invoices where id='bd000000-0000-4000-8000-000000000031'),'bd000000-0000-4000-8000-000000000041')$$,'discounted inclusive invoice issues');
