select is(private.document_tax_totals('[{"amount_satang":10000,"tax_rate_bps":0},{"amount_satang":10000,"tax_rate_bps":700},{"amount_satang":10000,"tax_rate_bps":1000}]',1,false,300)->>'amountDueSatang','30799','mixed-rate largest-remainder discount agrees with pure math');

