select public.submit_internal_payment_claim('bd000000-0000-4000-8000-000000000010','bd000000-0000-4000-8000-000000000030',104000,'Synthetic net transfer','bd000000-0000-4000-8000-000000000071');
select lives_ok($$select public.review_payment_claim_with_evidence('bd000000-0000-4000-8000-000000000010',(select id from public.payment_claims where invoice_id='bd000000-0000-4000-8000-000000000030' and status='pending'),104000,'Synthetic bank evidence','bd000000-0000-4000-8000-000000000072','verified',(now() at time zone 'Asia/Bangkok')::date,'transfer')$$,'net verified receipt settles VAT/WHT invoice');
select is((select status::text from public.invoices where id='bd000000-0000-4000-8000-000000000030'),'paid','paid status compares against amount due');
